bool ScriptSession::acceptsResource(const UnitState& depot,unsigned resource) {if(depot.productionBlocked() || depot.removing || depot.construction || depot.unsummon || depot.paused || depot.stunned() || depot.hidden() || number(depot.life)<=0)return false;auto [id,level]=sourceAbility(depot,"Artn");return id && definitions().number(id,"AbilityData",std::string(resource==1?"DataA":"DataB")+std::to_string(level))!=0;}
